package com.aoo.bcg.gifting;
import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Clock;import java.util.HexFormat;
public final class PlayerAuthenticator {private final byte[] secret;private final Clock clock;public PlayerAuthenticator(String s,Clock c){if(s==null||s.length()<32)throw new IllegalArgumentException("gifting auth secret must be at least 32 characters");secret=s.getBytes(StandardCharsets.UTF_8);clock=c;}public long authenticate(String h){try{if(h==null||!h.startsWith("Bearer "))throw new Exception();String[]p=h.substring(7).split("\\.",-1);long id=Long.parseLong(p[0]),expiry=Long.parseLong(p[1]),now=clock.instant().getEpochSecond();if(p.length!=3||id<=0||expiry<now||expiry>now+300)throw new Exception();Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret,"HmacSHA256"));if(!MessageDigest.isEqual(m.doFinal((p[0]+"."+p[1]).getBytes(StandardCharsets.UTF_8)),HexFormat.of().parseHex(p[2])))throw new Exception();return id;}catch(Exception e){throw new SecurityException("valid player bearer required");}}}
